(54, 'Cancellation of Approved Annual Leave', '<p>I am writing to request the cancellation of my approved annual leave which was scheduled from March 20, 2026 to April 10, 2026.</p><p><br></p>', 'general', '1', NULL, 114, '2026-03-16 14:41:43', '2026-03-16 14:41:43', NULL, NULL, 'uploads/communications/1773664903_e5977ebfa45c4595.pdf', ''),
(55, 'Nkumenyekanisha igikoresho cyangiritse', '<p>Nyakubahwa muyobozi (ED), 
Mbandikiye mbamenyesha ko nagize impanuka ndikuri moto nkagwa imashini ikora EBM ikangirika screen kwa (5) Le 13/03/2026</p><p>Nkaba nayijyanye kuba technicians bakambwira ko itakorwa kuko nta piece yayo iboneka bicyo tukaba twifuza kumenya niba harindi yayisimbura</p><p>tubaye dutegereje igisubizo cyanyu.

Murakoze
NDUWAYO Ephta - Gahanga site</p>', 'general', '3,4,5,7', '4,5', 80, '2026-03-16 15:37:24', '2026-03-23 17:50:49', NULL, NULL, NULL, NULL),
(56, 'Request for Examination Leave Permission', '<p><strong>Dear HR,  </strong></p><p>I hope you’re doing well.  </p><p>I’m writing to request permission to take the provision exam at Muhima Police Station (Nyarugenge).  </p><p>I’ve copied the ED’s office (Assistant to ED – Claudine) for awareness.  </p><p><br></p><p>Thank you for your understanding.  </p><p>Kind regards,  </p>', 'permission', '4,1', NULL, 2, '2026-03-17 10:05:07', '2026-03-17 10:05:07', '2026-03-17 14:00:00', '2026-03-17 17:00:00', NULL, NULL),
(57, 'Request permission', '<p><em>Dear HR</em></p><p><em><br></em></p><p><strong><em><u>Subject</u></em></strong>: Request for Permission </p><p><br></p><p>I hope this message finds you well. </p><p>I am writing to kindly request your permission which I would like to schedule starting from 14:00 in the afternoon. </p><p><br></p><p>Thank you for considering my request.</p><p> </p><p>I look forward to your approval.</p>', 'permission', '4', NULL, 3, '2026-03-17 10:46:38', '2026-03-17 10:46:38', '2026-03-17 10:45:00', '2026-03-17 10:45:00', NULL, NULL),
(58, 'REQUEST FOR PERMISSION TO PROCESS REFUND', '<p>I would like to request a refund for the imvoice because the tin number  was incorrect .</p><p>$he client asked me to process  it using correct  tin number ,as the previous one wa </p><p>mistaken and has now been corrected.</p><p><br></p><p><br></p><p>Thank you</p>', 'permission', '3', '3', 71, '2026-03-19 01:28:56', '2026-09-03 16:09:31', '2026-03-18 01:24:00', '2026-03-18 01:24:00', NULL, NULL),
(66, 'gusaba gukora refund', '<p>mwaramutse  neza,</p><p><br></p><p>nasabaga gukora refund umu client yaribeshye ampa tin number yacuritse imibare none yansabye gukorera </p><p>kuri tin nyayo,tin 107574658ni yari yampaye 105774658</p>', 'general', '3', '3', 71, '2026-03-20 11:02:37', '2026-03-20 20:54:14', NULL, NULL, NULL, NULL),
(67, 'Asking for payment of security', '<p>Good evening,This file below is letter asking for payment of security at Bishenyi ICPCS</p>', 'general', '3,7', NULL, 74, '2026-03-21 22:06:41', '2026-03-21 22:06:41', NULL, NULL, 'uploads/communications/1774123601_3144baf99a199f0b.pdf', ''),
(68, 'Asking for payment of security', '<p>Good evening, the file below is letter asking for payment of security at Bishenyi ICPCS </p>', 'general', '3,7', NULL, 74, '2026-03-21 22:09:38', '2026-03-21 22:09:38', NULL, NULL, 'uploads/communications/1774123778_11b200934f604b0c.pdf', ''),
(69, 'Asking for payment of security', '<p>Good evening, the file bellow is letter asking for payment of security at Bishenyi ICPC</p>', 'general', '3', NULL, 74, '2026-03-21 22:12:03', '2026-03-21 22:12:03', NULL, NULL, 'uploads/communications/1774123923_0a73a842078747fd.pdf', ''),
