(83, 'WEEKLY REPORT', 'Weekly', '<p>Dear Chantal,</p><p>Hello!</p><p><br></p><p><br></p><p>Herewith attached WEEKLY REPORT,</p><p><br></p><p>Best regards,</p><p><br></p><p>Balaka</p><p><br></p><p>Membership relations officer,</p><p><br></p><p>SDC RUBAVU</p>', '2026-03-16', '2026-03-22', 82, '2026-03-23 07:52:32', '2026-03-23 07:52:32', NULL, NULL, 'RUBAVU'),
(84, 'WEEKLY REPORT', 'Weekly', '<p>Mwaramutse neza,</p><p><br></p><p>Mboherereje raporo y''icyumweru kuva kuwa  16 Werurwe kugeza kuwa 22 Werurwe 2026</p><p><br></p><p>Murakoze cyane.</p><p><br></p><p><br></p><p>Anastase NTIRENGANYA</p><p><br></p><p>Site: Karongi - Rutsiro</p>', '2026-03-16', '2026-03-22', 112, '2026-03-23 08:00:18', '2026-03-23 08:00:18', '09:55:00', '09:55:00', 'Karongi - Rutsiro'),
(85, 'DAILY REPORT', 'Activity', '<p>Mwiriwe neza,</p><p><br></p><p>Mboherereje raporo yo kuwa 22 Werurwe 2026</p><p><br></p><p><br></p><p>Murakoze.</p><p><br></p><p>Anastase NTIRENGANYA</p><p><br></p><p>Site: Karongi - Rutsiro</p><p><br></p>', '2026-03-22', '2026-03-22', 112, '2026-03-23 08:06:45', '2026-03-23 08:06:45', '16:01:00', '16:02:00', 'Karongi - Rutsiro'),
(86, 'WEEK REPORT', 'Weekly', '<p>WEEK REPORT FROM 16 TO 22 MARCH 2026</p><p><br></p><p>Dufite ikibazo cyuko Imvura yaguye arinyinshi cyane Bityo bituma abacuruzi batabona imbaho kuko zabuze uko ziva mwishyamba</p>', '2026-03-16', '2026-03-22', 101, '2026-03-23 08:16:21', '2026-03-23 08:16:21', '09:00:00', '10:20:00', 'KIMIRONKO ICPCs'),
